+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Snake Game</title>
+    <style>
+        body {
+            background: rgba(15, 23, 42, 0.8);
+            backdrop-filter: blur(20px);
+            font-family: 'Inter', sans-serif;
+        }
+        .game-container {
+            max-width: 600px;
+            padding: 28px;
+            border-radius: 20px;
+            display: flex;
+            flex-direction: column;
+            align-items: center;
+            justify-content: center;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.35);
+        }
+        .score {
+            font-size: 24px;
+            font-weight: bold;
+            color: #F8FAFC;
+            margin-bottom: 20px;
+        }
+        .game-canvas {
+            border: 1px solid #F8FAFC;
+            border-radius: 10px;
+        }
+    </style>
+</head>
+<body>
+    <div class="game-container">
+        <div class="score">Score: <span id="score">0</span></div>
+        <canvas id="game-canvas" width="400" height="400" class="game-canvas"></canvas>
+        <button id="start-game">Start Game</button>
+        <button id="replay-game" style="display: none;">Replay Game</button>
+    </div>
+    <script>
+        const canvas = document.getElementById('game-canvas');
+        const ctx = canvas.getContext('2d');
+        const scoreElement = document.getElementById('score');
+        const startGameButton = document.getElementById('start-game');
+        const replayGameButton = document.getElementById('replay-game');
+        let score = 0;
+        let highScore = localStorage.getItem('highScore') || 0;
+        let snake = [
+            { x: 200, y: 200 },
+            { x: 190, y: 200 },
+            { x: 180, y: 200 }
+        ];
+        let direction = 'right';
+        let food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+        let gameInterval;
+        
+        startGameButton.addEventListener('click', startGame);
+        replayGameButton.addEventListener('click', replayGame);
+        document.addEventListener('keydown', handleKeyDown);
+        
+        function startGame() {
+            score = 0;
+            snake = [
+                { x: 200, y: 200 },
+                { x: 190, y: 200 },
+                { x: 180, y: 200 }
+            ];
+            direction = 'right';
+            food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+            gameInterval = setInterval(draw, 100);
+            startGameButton.style.display = 'none';
+        }
+        
+        function replayGame() {
+            startGame();
+        }
+        
+        function handleKeyDown(event) {
+            switch (event.key) {
+                case 'ArrowUp':
+                    if (direction !== 'down') direction = 'up';
+                    break;
+                case 'ArrowDown':
+                    if (direction !== 'up') direction = 'down';
+                    break;
+                case 'ArrowLeft':
+                    if (direction !== 'right') direction = 'left';
+                    break;
+                case 'ArrowRight':
+                    if (direction !== 'left') direction = 'right';
+                    break;
+            }
+        }
+        
+        function draw() {
+            ctx.clearRect(0, 0, canvas.width, canvas.height);
+            ctx.fillStyle = 'rgba(56, 189, 248, 0.35)';
+            ctx.fillRect(0, 0, canvas.width, canvas.height);
+            
+            for (let i = 0; i < snake.length; i++) {
+                ctx.fillStyle = 'rgba(56, 189, 248, 0.5)';
+                ctx.fillRect(snake[i].x, snake[i].y, 10, 10);
+            }
+            
+            ctx.fillStyle = 'rgba(255, 0, 0, 0.5)';
+            ctx.fillRect(food.x, food.y, 10, 10);
+            
+            moveSnake();
+            checkCollision();
+            updateScore();
+        }
+        
+        function moveSnake() {
+            let head = { x: snake[0].x, y: snake[0].y };
+            
+            switch (direction) {
+                case 'up':
+                    head.y -= 10;
+                    break;
+                case 'down':
+                    head.y += 10;
+                    break;
+                case 'left':
+                    head.x -= 10;
+                    break;
+                case 'right':
+                    head.x += 10;
+                    break;
+            }
+            
+            snake.unshift(head);
+            
+            if (snake[0].x === food.x && snake[0].y === food.y) {
+                score++;
+                food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+            } else {
+                snake.pop();
+            }
+        }
+        
+        function checkCollision() {
+            if (snake[0].x < 0 || snake[0].x >= canvas.width || snake[0].y < 0 || snake[0].y >= canvas.height) {
+                gameOver();
+            }
+            
+            for (let i = 1; i < snake.length; i++) {
+                if (snake[0].x === snake[i].x && snake[0].y === snake[i].y) {
+                    gameOver();
+                }
+            }
+        }
+        
+        function updateScore() {
+            scoreElement.textContent = score;
+            if (score > highScore) {
+                highScore = score;
+                localStorage.setItem('highScore', highScore);
+            }
+        }
+        
+        function gameOver() {
+            clearInterval(gameInterval);
+            replayGameButton.style.display = 'block';
+        }
+    </script>
+</body>
+</html>

